function calibration = calibrateFocusedIsmMonomerBrightness(sparseResult)
%CALIBRATEFOCUSEDISMMONOMERBRIGHTNESS Calibrate shared BNP brightness.
%
%   calibration = calibrateFocusedIsmMonomerBrightness(sparseResult)
%
%   sparseResult must come from a low-concentration focused-ISM acquisition
%   or simulation with isolated, identifiable monomer localizations. The
%   returned scale is relative to the photon flux predicted by the forward
%   photophysics model at each fitted position.

    requiredFields = {'localizationTable', 'detector', 'options'};
    for field = requiredFields
        if ~isfield(sparseResult, field{1})
            error('calibrateFocusedIsmMonomerBrightness:MissingField', ...
                'sparseResult is missing field %s.', field{1});
        end
    end

    localization = sparseResult.localizationTable;
    requiredVariables = {'xUm', 'yUm', 'signalPhotons', ...
        'jointEmitterCount', 'emitterCountPosteriorProbability', ...
        'positionIdentifiable'};
    if ~all(ismember(requiredVariables, ...
            localization.Properties.VariableNames))
        error('calibrateFocusedIsmMonomerBrightness:BadTable', ...
            'The localization table lacks required focused-ISM variables.');
    end

    usable = localization.jointEmitterCount == 1 & ...
        localization.emitterCountPosteriorProbability >= 0.90 & ...
        localization.positionIdentifiable & ...
        isfinite(localization.signalPhotons) & ...
        localization.signalPhotons > 0;
    selected = localization(usable,:);
    predicted = membrane_tracking.focused_ism.bnpEmitterContribution( ...
        [selected.xUm selected.yUm], sparseResult.detector, ...
        sparseResult.options, 1);
    predictedSignal = sum(predicted, 2);
    highInformation = predictedSignal >= ...
        5 * sparseResult.options.minPhotonsPerLocalization & ...
        selected.signalPhotons >= ...
        5 * sparseResult.options.minPhotonsPerLocalization;
    selected = selected(highInformation,:);
    predictedSignal = predictedSignal(highInformation);
    if height(selected) < 20
        error('calibrateFocusedIsmMonomerBrightness:TooFewFrames', ...
            ['At least 20 bright isolated monomer localizations are ' ...
            'required; only %d passed the calibration filters.'], ...
            height(selected));
    end

    scaleSamples = selected.signalPhotons ./ ...
        max(predictedSignal, realmin);
    scaleSamples = scaleSamples(isfinite(scaleSamples) & scaleSamples > 0);
    scaleMedian = median(scaleSamples);
    absoluteDeviation = median(abs(scaleSamples - scaleMedian));
    robustStandardDeviation = 1.4826 * absoluteDeviation;
    relativeScatter = robustStandardDeviation / ...
        max(scaleMedian, realmin);
    relativeStandardError = relativeScatter / sqrt(numel(scaleSamples));

    calibration = struct();
    calibration.brightnessScale = scaleMedian;
    calibration.relativeScatter = relativeScatter;
    calibration.relativeStandardErrorApprox = relativeStandardError;
    calibration.nAcceptedLocalizations = numel(scaleSamples);
    calibration.recommendedBrightnessMode = 'fixed';
    calibration.recommendedArguments = { ...
        'bnpBrightnessMode', 'fixed', ...
        'bnpCalibratedBrightnessScale', scaleMedian};
    calibration.note = [ ...
        'Use a separate sparse monomer acquisition. Repeated frames from ' ...
        'one molecule are correlated, so relativeStandardErrorApprox can ' ...
        'be optimistic.'];
end
